// Processa e filtra os eventos da Evolution API
const body = $json.body || $json;

// Verifica se é evento de mensagem
const event = body.event || '';
if (event !== 'messages.upsert' && event !== 'MESSAGES_UPSERT') {
  return [];
}

const data = body.data;
if (!data) return [];

// Ignora mensagens enviadas pelo próprio bot (evita loop infinito)
if (data.key?.fromMe === true) {
  return [];
}

// Ignora grupos (se for o caso)
const remoteJid = data.key?.remoteJid || '';
if (remoteJid.includes('@g.us')) {
  return [];
}

// Extrai o texto da mensagem
const msg = data.message;
let text = '';
if (msg) {
  text = msg.conversation || msg.extendedTextMessage?.text || msg.imageMessage?.caption || '';
}

if (!text || !text.trim()) {
  return [];
}

const senderNumber = remoteJid.replace('@s.whatsapp.net', '');
const instanceName = body.instance || 'meu-bot';

return [
  {
    json: {
      text: text.trim(),
      sender: remoteJid,
      senderNumber: senderNumber,
      pushName: data.pushName || 'Cliente',
      instance: instanceName
    }
  }
];
